package main

import (
	"crypto/rand"
	"fmt"
	"io"
	"log"
	"net/http"
	"path/filepath"
	"strings"
	"time"
)

// Object-upload limits and messages.
const (
	// uploadPrefix is the bucket-relative directory of a stored upload. The rest
	// of the key is generated by the server, so a caller never chooses the key
	// and never overwrites an object.
	uploadPrefix = "uploads/"
	// msgUploadFileRequired is answered when the body carries no file part.
	msgUploadFileRequired = "file required"
	// msgTooManyFiles is answered when the body carries more than one file part.
	msgTooManyFiles = "too many files"
)

// uploadResponse is the body of a 201 stored upload. URL is a presigned GET and
// ExpiresAt is the RFC 3339 UTC instant, at second precision, it stops working
// at, so the presigned URL is the only place a signature ever reaches the
// browser.
type uploadResponse struct {
	Key         string `json:"key"`
	URL         string `json:"url"`
	ExpiresAt   string `json:"expiresAt"`
	Size        int64  `json:"size"`
	ContentType string `json:"contentType"`
}

// presignTTLSource is implemented by an object store that knows the configured
// S3_PRESIGN_TTL_SECONDS, so a handler can report the instant its presigned URL
// stops working at instead of guessing the lifetime.
type presignTTLSource interface {
	presignLifetime() time.Duration
}

// presignLifetime is the lifetime of a presigned GET: the lifetime the store
// signs with when it carries one, the documented default otherwise.
func presignLifetime(storage objectStorage) time.Duration {
	if configured, ok := storage.(presignTTLSource); ok {
		if ttl := configured.presignLifetime(); ttl > 0 {
			return ttl
		}
	}
	return defaultPresignTTLSeconds * time.Second
}

// uploadFile stores exactly one uploaded CSV in the private bucket under a
// server-generated key and answers with a short-lived presigned GET for it. A
// nil storage leaves the route answering 503, so the service still boots and
// serves every synchronous route without an object-store configuration.
func uploadFile(storage objectStorage, now func() time.Time) http.HandlerFunc {
	if now == nil {
		now = time.Now
	}

	return func(w http.ResponseWriter, r *http.Request) {
		if storage == nil {
			writeStorageFailure(w, errStorageNotConfigured)
			return
		}

		data, _, status, message := readUploadFile(r)
		if status != 0 {
			writeJSON(w, status, map[string]string{"error": message})
			return
		}

		key, err := newObjectKey(uploadPrefix)
		if err != nil {
			log.Printf("catalog upload: %v", err)
			writeStorageFailure(w, errStorageUnavailable)
			return
		}

		if err := storage.Put(r.Context(), key, data, csvContentType); err != nil {
			log.Printf("catalog upload: storing %q: %v", key, err)
			writeStorageFailure(w, errStorageUnavailable)
			return
		}

		ttl := presignLifetime(storage)
		url, err := storage.PresignGet(r.Context(), key, ttl)
		if err != nil {
			log.Printf("catalog upload: presigning %q: %v", key, err)
			writeStorageFailure(w, errStorageUnavailable)
			return
		}

		writeJSON(w, http.StatusCreated, uploadResponse{
			Key:         key,
			URL:         url,
			ExpiresAt:   now().Add(ttl).UTC().Truncate(time.Second).Format(time.RFC3339),
			Size:        int64(len(data)),
			ContentType: csvContentType,
		})
	}
}

// readUploadFile reads the single file part of a multipart request. A status of
// 0 means data is usable; otherwise status and message describe the answer. No
// request field is ever read as an object key, and the file part is read through
// a limit of maxImportBytes+1 bytes so the size cap holds while the body is
// being read. The returned filename is the name of that part.
func readUploadFile(r *http.Request) (data []byte, filename string, status int, message string) {
	reader, err := r.MultipartReader()
	if err != nil {
		return nil, "", http.StatusBadRequest, msgUploadFileRequired
	}

	files := 0
	for {
		part, err := reader.NextPart()
		if err != nil {
			// The body is exhausted: no file part at all is refused, and the one
			// file part read so far is the whole upload.
			if files == 0 {
				return nil, "", http.StatusBadRequest, msgUploadFileRequired
			}
			return data, filename, 0, ""
		}

		name := part.FileName()
		if name == "" {
			_ = part.Close()
			continue
		}

		files++
		if files > 1 {
			_ = part.Close()
			return nil, "", http.StatusBadRequest, msgTooManyFiles
		}

		if !strings.EqualFold(filepath.Ext(name), ".csv") {
			_ = part.Close()
			return nil, "", http.StatusUnsupportedMediaType, msgUnsupportedType
		}

		raw, err := io.ReadAll(io.LimitReader(part, maxImportBytes+1))
		_ = part.Close()
		if err != nil {
			return nil, "", http.StatusBadRequest, msgUploadFileRequired
		}
		if len(raw) > maxImportBytes {
			return nil, "", http.StatusRequestEntityTooLarge, msgFileTooLarge
		}
		data, filename = raw, name
	}
}

// newObjectKey returns a fresh bucket-relative key under prefix whose name is
// generated from crypto/rand, so two uploads never share a key and a caller
// cannot pick one.
func newObjectKey(prefix string) (string, error) {
	var raw [16]byte
	if _, err := rand.Read(raw[:]); err != nil {
		return "", fmt.Errorf("generating an object key: %w", err)
	}

	raw[6] = (raw[6] & 0x0f) | 0x40 // version 4
	raw[8] = (raw[8] & 0x3f) | 0x80 // RFC 4122 variant

	return fmt.Sprintf("%s%x-%x-%x-%x-%x.csv", prefix, raw[0:4], raw[4:6], raw[6:8], raw[8:10], raw[10:16]), nil
}
